INSERT INTO hotel(id,name,slug,description,address,city,country,timezone,status) VALUES
('10000000-0000-4000-8000-000000000010','Banteay Chhmar Gate Hotel','banteay-chhmar-gate-hotel','A quiet stop on National Road 5 and the gateway to the remote temple complex of Banteay Chhmar.','National Road 5, Serei Saophoan','Banteay Meanchey (Serei Saophoan)','Cambodia','Asia/Phnom_Penh','APPROVED'),
('10000000-0000-4000-8000-000000000011','Bamboo Bridge Riverside Inn','bamboo-bridge-riverside-inn','Mekong riverfront rooms close to the seasonal bamboo bridge to Koh Paen and the temple of Wat Nokor.','Preah Bat Sihanouk Street, Kampong Cham','Kampong Cham','Cambodia','Asia/Phnom_Penh','APPROVED'),
('10000000-0000-4000-8000-000000000012','Floating Village Guesthouse','floating-village-guesthouse','Simple rooms near the Tonle Sap river port, with boat trips to the floating villages and visits to local pottery workshops.','Krong Kampong Chhnang, near the river port','Kampong Chhnang','Cambodia','Asia/Phnom_Penh','APPROVED'),
('10000000-0000-4000-8000-000000000013','Kirirom Pine Lodge','kirirom-pine-lodge','Cabins on the road to Kirirom National Park, known for its pine forest, and to the palm sugar farms of Kampong Speu.','National Road 4, Chbar Mon','Kampong Speu (Chbar Mon)','Cambodia','Asia/Phnom_Penh','APPROVED'),
('10000000-0000-4000-8000-000000000014','Sambor Prei Kuk Heritage Stay','sambor-prei-kuk-heritage-stay','A base for the pre-Angkorian temples of Sambor Prei Kuk, a UNESCO World Heritage Site, and the hilltop pagodas of Phnom Santuk.','Street 6, Stung Sen','Kampong Thom (Stung Sen)','Cambodia','Asia/Phnom_Penh','APPROVED'),
('10000000-0000-4000-8000-000000000015','Mekong Silk Retreat','mekong-silk-retreat','Riverside bungalows 30 minutes from Phnom Penh, close to the silk-weaving villages of Koh Dach.','National Road 2, Ta Khmau','Kandal (Ta Khmau)','Cambodia','Asia/Phnom_Penh','APPROVED'),
('10000000-0000-4000-8000-000000000016','Dangrek Mountain Lodge','dangrek-mountain-lodge','A lodge in Cambodia''s far north for trips to Anlong Veng, the Dangrek escarpment and the border temple of Prasat Ta Muen.','National Road 68, Samraong','Oddar Meanchey (Samraong)','Cambodia','Asia/Phnom_Penh','APPROVED'),
('10000000-0000-4000-8000-000000000017','Gemstone Hill Resort','gemstone-hill-resort','A hillside resort in Pailin, known for its gem-mining history, fruit orchards and the hilltop pagoda of Phnom Yat.','Phnom Yat Road, Pailin','Pailin','Cambodia','Asia/Phnom_Penh','APPROVED'),
('10000000-0000-4000-8000-000000000018','Preah Vihear Temple View Hotel','preah-vihear-temple-view-hotel','A comfortable base for the cliff-top temple of Prasat Preah Vihear and the jungle temples of Koh Ker.','Krong Preah Vihear, Tbeng Meanchey','Preah Vihear','Cambodia','Asia/Phnom_Penh','APPROVED'),
('10000000-0000-4000-8000-000000000019','Ba Phnom Riverside Homestay','ba-phnom-riverside-homestay','A family-run homestay in the Mekong countryside, close to the historic hill and pagodas of Ba Phnom.','Krong Prey Veng, near the provincial market','Prey Veng','Cambodia','Asia/Phnom_Penh','APPROVED'),
('10000000-0000-4000-8000-000000000020','Cardamom Marble Inn','cardamom-marble-inn','A town-centre inn known for Pursat''s marble carving, with day trips to the Kampong Luong floating village and the Cardamom Mountains.','Street 1, Krong Pursat','Pursat','Cambodia','Asia/Phnom_Penh','APPROVED'),
('10000000-0000-4000-8000-000000000021','Yeak Laom Crater Lodge','yeak-laom-crater-lodge','Bungalows on the red-earth hills of Banlung, a short ride from Yeak Laom crater lake and the edge of Virachey National Park.','Boeng Kansaeng Road, Banlung','Ratanakiri (Banlung)','Cambodia','Asia/Phnom_Penh','APPROVED'),
('10000000-0000-4000-8000-000000000022','Mekong Wetlands Guesthouse','mekong-wetlands-guesthouse','Riverfront rooms where the Sekong meets the Mekong, for boat trips to the Ramsar-listed wetlands and the Irrawaddy dolphins.','Riverside Road, Krong Stung Treng','Stung Treng','Cambodia','Asia/Phnom_Penh','APPROVED'),
('10000000-0000-4000-8000-000000000023','Bavet Garden Hotel','bavet-garden-hotel','A garden hotel on National Road 1, between Phnom Penh and the Bavet border crossing, close to the riverside park of Svay Rieng town.','National Road 1, Krong Svay Rieng','Svay Rieng','Cambodia','Asia/Phnom_Penh','APPROVED'),
('10000000-0000-4000-8000-000000000024','Phnom Da Lakeside Inn','phnom-da-lakeside-inn','A lakeside inn in Takeo town, with boat trips to the ancient city of Angkor Borei and the hilltop temple of Phnom Da.','Lakeside Road, Doun Kaev','Takeo (Doun Kaev)','Cambodia','Asia/Phnom_Penh','APPROVED'),
('10000000-0000-4000-8000-000000000025','Rubber Garden Lodge','rubber-garden-lodge','A quiet lodge among the rubber plantations of Tbong Khmum, Cambodia''s newest province.','National Road 7, Suong','Tbong Khmum (Suong)','Cambodia','Asia/Phnom_Penh','APPROVED');
