-- Local/demo data only (db/local). Adds one fictional hotel for each province not covered by V901, so
-- every one of Cambodia's 24 provinces and the capital, Phnom Penh, has bookable demo inventory.
-- Provincial capitals are from https://en.wikipedia.org/wiki/Provinces_of_Cambodia. Hotel names are fictional.

-- Official province name first, so searching Preah Sihanouk, Kampong Som or Sihanoukville all match.
UPDATE hotel SET city='Preah Sihanouk (Kampong Som, Sihanoukville)',updated_at=now() WHERE id='10000000-0000-4000-8000-000000000003';





-- Same seasonal pattern as V901: dry high season and Khmer New Year.
SELECT id,DATE '2026-12-01',DATE '2027-02-01',round(base_price*1.20,0),currency,1 FROM room_type WHERE hotel_id BETWEEN '10000000-0000-4000-8000-000000000010' AND '10000000-0000-4000-8000-000000000025'
UNION ALL
SELECT id,DATE '2027-04-13',DATE '2027-04-17',round(base_price*1.35,0),currency,10 FROM room_type WHERE hotel_id BETWEEN '10000000-0000-4000-8000-000000000010' AND '10000000-0000-4000-8000-000000000025';
